pub(crate) fn find(key: &str) -> Option<&'static str> {
    if key >= "эвфемизирующий" {
        return m35(key);
    }
    if key >= "шинирующий" {
        return m34(key);
    }
    if key >= "чаявшийся" {
        return m33(key);
    }
    if key >= "химичащийся" {
        return m32(key);
    }
    if key >= "фибриллируемый" {
        return m31(key);
    }
    if key >= "утонившийся" {
        return m30(key);
    }
    if key >= "упразднившийся" {
        return m29(key);
    }
    if key >= "укоряющийся" {
        return m28(key);
    }
    if key >= "убоживший" {
        return m27(key);
    }
    if key >= "топырившийся" {
        return m26(key);
    }
    if key >= "табелировавший" {
        return m25(key);
    }
    if key >= "стушевывающийся" {
        return m24(key);
    }
    if key >= "ссасывавшийся" {
        return m23(key);
    }
    if key >= "состругиваемый" {
        return m22(key);
    }
    if key >= "смучивший" {
        return m21(key);
    }
    if key >= "скорчивающий" {
        return m20(key);
    }
    if key >= "серьезничающий" {
        return m19(key);
    }
    if key >= "сбыченный" {
        return m18(key);
    }
    if key >= "рубцевавший" {
        return m17(key);
    }
    if key >= "результирующийся" {
        return m16(key);
    }
    if key >= "расхреначенный" {
        return m15(key);
    }
    if key >= "расстарывающийся" {
        return m14(key);
    }
    if key >= "распечатывающийся" {
        return m13(key);
    }
    if key >= "раскабаляемый" {
        return m12(key);
    }
    if key >= "разменивавшийся" {
        return m11(key);
    }
    if key >= "развоплощающий" {
        return m10(key);
    }
    if key >= "пудривавшийся" {
        return m9(key);
    }
    if key >= "противуполагающий" {
        return m8(key);
    }
    if key >= "пропятивший" {
        return m7(key);
    }
    if key >= "промаливавшийся" {
        return m6(key);
    }
    if key >= "проебывавшийся" {
        return m5(key);
    }
    if key >= "прищепляющий" {
        return m4(key);
    }
    if key >= "притачивающий" {
        return m3(key);
    }
    if key >= "приплюскивавший" {
        return m2(key);
    }
    if key >= "прилуняемый" {
        return m1(key);
    }
    m0(key)
}

